#!/usr/bin/env python3
"""Validate the normal-path PKI matrix generated by make-pki.sh."""

import os
from datetime import datetime, timedelta, timezone
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile


CERTIFICATE = re.compile(
    rb"-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----", re.DOTALL
)


def check(condition, message):
    if not condition:
        raise RuntimeError(message)


def run(command, *, env=None, certificate=None):
    return subprocess.run(
        [str(part) for part in command],
        check=True,
        capture_output=True,
        input=certificate,
        env=env,
    )


def certificates(path):
    return CERTIFICATE.findall(path.read_bytes())


def identity(openssl, certificate):
    output = run(
        [openssl, "x509", "-noout", "-subject", "-issuer", "-nameopt", "RFC2253"],
        certificate=certificate,
    ).stdout.decode()
    values = {}
    for line in output.splitlines():
        name, value = line.split("=", 1)
        values[name] = value
    return values["subject"], values["issuer"]


def validity(openssl, path):
    output = run(
        [openssl, "x509", "-in", path, "-noout", "-dateopt", "iso_8601", "-dates"]
    ).stdout.decode()
    values = {}
    for line in output.splitlines():
        name, value = line.split("=", 1)
        values[name] = datetime.strptime(value, "%Y-%m-%d %H:%M:%SZ").replace(
            tzinfo=timezone.utc
        )
    return values["notBefore"], values["notAfter"]


def expected_intermediates(chain_length):
    root = "CN=TURTLE Test Root"
    result = []
    for level in range(chain_length - 1, 0, -1):
        subject = f"CN=TURTLE Test Intermediate {level}"
        issuer = root if level == 1 else f"CN=TURTLE Test Intermediate {level - 1}"
        result.append((subject, issuer))
    return result


def check_public_key(openssl, path, algorithm):
    text = run([openssl, "x509", "-in", path, "-noout", "-text"]).stdout.decode()
    expected = {
        "ecdsa": ("Public Key Algorithm: id-ecPublicKey", "Public-Key: (256 bit)",
                  "ASN1 OID: prime256v1"),
        "rsa": ("Public Key Algorithm: rsaEncryption", "Public-Key: (2048 bit)"),
        "ed25519": ("Public Key Algorithm: ED25519",),
    }[algorithm]
    check(all(fragment in text for fragment in expected),
          f"{path.name}: wrong {algorithm} leaf public key")
    check("Signature Algorithm: ecdsa-with-SHA256" in text,
          f"{path.name}: certificate was not signed by the ECDSA CA")


def verify_leaf(openssl, directory, role, chain_length):
    purpose = "sslserver" if role == "server" else "sslclient"
    command = [openssl, "verify", "-purpose", purpose]
    if role == "server":
        command += ["-verify_hostname", "localhost"]
    command += ["-CAfile", directory / "ca.pem"]
    if chain_length > 1:
        command += ["-untrusted", directory / "intermediates.pem"]
    command += [directory / f"{role}.pem"]
    output = run(command).stdout.decode()
    check(output.rstrip().endswith(": OK"), f"{role}: OpenSSL verification did not pass")


def validate(openssl, directory, algorithm, chain_length):
    root_name = "CN=TURTLE Test Root"
    root = certificates(directory / "ca.pem")
    check(len(root) == 1, "root bundle must contain exactly one certificate")
    check(identity(openssl, root[0]) == (root_name, root_name), "wrong root identity")
    common_validity = validity(openssl, directory / "ca.pem")
    check(common_validity[1] - common_validity[0] == timedelta(days=3650, seconds=300),
          "root validity does not include the expected five-minute backdate")
    root_text = run(
        [openssl, "x509", "-in", directory / "ca.pem", "-noout", "-text"]
    ).stdout.decode()
    check("Public Key Algorithm: id-ecPublicKey" in root_text and
          "ASN1 OID: prime256v1" in root_text and
          "Signature Algorithm: ecdsa-with-SHA256" in root_text,
          "root CA is not ECDSA P-256")

    expected = expected_intermediates(chain_length)
    intermediate_certs = certificates(directory / "intermediates.pem")
    observed = [identity(openssl, cert) for cert in intermediate_certs]
    check(observed == expected, "intermediate bundle count or leaf-to-root order is wrong")
    for level in range(1, chain_length):
        certs = certificates(directory / f"intermediate-{level}.pem")
        check(len(certs) == 1, f"intermediate-{level} must contain one certificate")
        expected_identity = next(item for item in expected
                                 if item[0] == f"CN=TURTLE Test Intermediate {level}")
        check(identity(openssl, certs[0]) == expected_identity,
              f"intermediate-{level} has the wrong issuer")
        check(validity(openssl, directory / f"intermediate-{level}.pem") == common_validity,
              f"intermediate-{level} does not use the common validity window")

    snapshot = {"root": [identity(openssl, root[0])], "intermediates": observed}
    issuer = root_name if chain_length == 1 else f"CN=TURTLE Test Intermediate {chain_length - 1}"
    for role in ("server", "client"):
        leaf = certificates(directory / f"{role}.pem")
        check(len(leaf) == 1, f"{role}.pem must contain one certificate")
        leaf_identity = identity(openssl, leaf[0])
        check(leaf_identity == (f"CN={role}", issuer), f"{role}: wrong leaf issuer")
        check(validity(openssl, directory / f"{role}.pem") == common_validity,
              f"{role}: does not use the common validity window")
        chain = certificates(directory / f"{role}-chain.pem")
        chain_identities = [identity(openssl, cert) for cert in chain]
        check(chain_identities == [leaf_identity] + expected,
              f"{role}: chain count or leaf-to-root order is wrong")
        check_public_key(openssl, directory / f"{role}.pem", algorithm)
        verify_leaf(openssl, directory, role, chain_length)
        snapshot[role] = chain_identities
    return snapshot


def main():
    check(len(sys.argv) == 3, "usage: pki.py MAKE_PKI OPENSSL")
    make_pki, openssl = map(Path, sys.argv[1:])
    root = Path(tempfile.mkdtemp(prefix="turtle-pki-"))
    env = os.environ.copy()
    env["OPENSSL"] = str(openssl)
    try:
        for algorithm in ("ecdsa", "rsa", "ed25519"):
            for chain_length in (1, 2, 3):
                directory = root / f"leaf-{algorithm}-chain-{chain_length}"
                snapshots = []
                for _ in range(2):
                    run(["bash", make_pki, directory, algorithm, chain_length], env=env)
                    snapshots.append(validate(openssl, directory, algorithm, chain_length))
                check(snapshots[0] == snapshots[1],
                      f"{algorithm}/{chain_length}: regeneration changed PKI structure")
                print(f"PASS leaf={algorithm}, chain={chain_length}, issuer=ECDSA P-256")
        shutil.rmtree(root)
    except Exception as error:
        if isinstance(error, subprocess.CalledProcessError):
            print(error.stdout.decode(errors="replace"), file=sys.stderr)
            print(error.stderr.decode(errors="replace"), file=sys.stderr)
        print(f"Artifacts retained: {root}", file=sys.stderr)
        raise


if __name__ == "__main__":
    main()
